<script setup>
import {computed,ref,onMounted,onBeforeUnmount,watch,nextTick} from 'vue'
import {max,scaleLinear} from 'd3'
import {aggregate,filterRows,grouped,trailingPeriod,periodSeries} from './analytics.js'
import TrendChart from './TrendChart.vue'
const props=defineProps({data:Object,colors:Object,period:{type:String,default:'year'}})
const emit=defineEmits(['update:period','open-dashboard'])
const storyEl=ref(null),motion=ref(false)
const periods=[['week','Неделя'],['month','Месяц'],['quarter','Квартал'],['year','Год'],['all','Весь период']]
const phrases={week:'за последнюю неделю',month:'за последний месяц',quarter:'за последний квартал',year:'за последний год',all:'за весь период'}
const money=v=>v==null?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(v/100)+' ₽'
const number=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(v)
const pct=v=>v==null?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(v)+' %'
const date=v=>new Date(v+'T00:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'})
const range=computed(()=>trailingPeriod(props.period,props.data.audit.minDate,props.data.audit.maxDate))
const rangeLabel=computed(()=>date(range.value.start)+' — '+date(range.value.end))
const rows=computed(()=>filterRows(props.data.rows,props.data.products,range.value.start,range.value.end))
const summary=computed(()=>aggregate(rows.value,props.data.products))
const series=computed(()=>periodSeries(rows.value,props.data.products,range.value.start,range.value.end))
const months=computed(()=>series.value.values)
const cats=computed(()=>grouped(rows.value,props.data.products,r=>props.data.products[r.product].category).sort((a,b)=>b.spend-a.spend))
const products=computed(()=>grouped(rows.value.filter(r=>!props.data.products[r.product].service),props.data.products,r=>r.product).map(p=>({...p,...props.data.products[p.key]})))
const byQty=computed(()=>[...products.value].sort((a,b)=>b.quantity-a.quantity||b.spend-a.spend))
const byMoney=computed(()=>[...products.value].sort((a,b)=>b.spend-a.spend||b.quantity-a.quantity))
const sameLeader=computed(()=>byQty.value[0]?.id===byMoney.value[0]?.id)
const peak=computed(()=>months.value.reduce((best,m)=>m.spend>best.spend?m:best,months.value[0]))
const categoryWidth=computed(()=>scaleLinear().domain([0,max(cats.value,c=>c.spend)||1]).range([0,100]))
const dateName=k=>new Date((k.length===10?k:k+'-01')+'T00:00:00Z').toLocaleDateString('ru-RU',{day:k.length===10?'numeric':undefined,month:'long',year:'numeric',timeZone:'UTC'})
const history=computed(()=>byMoney.value[0]?periodSeries(rows.value.filter(r=>r.product===byMoney.value[0].id),props.data.products,range.value.start,range.value.end).values.map(p=>({key:p.key,value:p.quantity?p.spend/p.quantity:null})):[])
const purchases=computed(()=>history.value.filter(p=>p.value!=null))
const pic=p=>p.imageData||import.meta.env.BASE_URL+'items/'+p.image
const heroProducts=computed(()=>[...new Map([byQty.value[0],...byMoney.value.slice(0,5)].filter(Boolean).map(p=>[p.id,p])).values()].slice(0,4))
const threeShare=computed(()=>summary.value.spend?100*cats.value.slice(0,3).reduce((s,c)=>s+c.spend,0)/summary.value.spend:0)
const topCategoryNames=computed(()=>cats.value.slice(0,3).map(c=>c.key).join(', '))
let frame=0,lastOffset=0,lastHeight=768,reduced
function reveal(offset,height){lastOffset=offset;lastHeight=height;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(!storyEl.value)return;motion.value=!reduced.matches;for(const chapter of storyEl.value.querySelectorAll('.story-chapter,.story-invitation')){const top=chapter.getBoundingClientRect().top+window.scrollY;if(top-offset<height*.88)chapter.classList.add('is-revealed')}})}
function viewportMessage(e){if(e.source!==window.parent||e.data?.type!=='korzina-viewport')return;const {offset,height}=e.data;if(Number.isFinite(offset)&&Number.isFinite(height)&&height>0&&height<10000)reveal(offset,height)}
function ownScroll(){if(window.parent===window)reveal(window.scrollY,window.innerHeight)}
onMounted(()=>{reduced=window.matchMedia('(prefers-reduced-motion: reduce)');window.addEventListener('message',viewportMessage);window.addEventListener('scroll',ownScroll,{passive:true});window.addEventListener('resize',ownScroll);if(window.parent===window)ownScroll();else window.parent.postMessage({type:'korzina-viewport-request'},'*')})
watch(()=>props.period,async()=>{await nextTick();reveal(lastOffset,lastHeight)})
onBeforeUnmount(()=>{cancelAnimationFrame(frame);window.removeEventListener('message',viewportMessage);window.removeEventListener('scroll',ownScroll);window.removeEventListener('resize',ownScroll)})
</script>
<template>
 <div class="story" id="story" ref="storyEl" :class="{'motion-ready':motion}">
 <section class="story-hero"><div class="story-hero-copy"><div class="story-period-picker"><span class="story-kicker">КАКУЮ ИСТОРИЮ ПОСМОТРИМ?</span><div class="story-periods" role="group" aria-label="Период истории"><button v-for="[key,label] in periods" :key="key" :aria-pressed="period===key" :class="{active:period===key}" @click="emit('update:period',key)">{{label}}</button></div><p class="story-period-caption">От последней покупки в истории: {{date(data.audit.maxDate)}}</p></div><h1>Маленькие покупки.<br><span>Большая история.</span></h1><p>Молоко к завтраку, фрукты на неделю, что-то вкусное просто так. Посмотрите, какую картину складывают ваши повседневные покупки.</p><a class="story-start" href="#story-overview">Узнать свою корзину <span>↓</span></a></div><div class="story-cover" aria-label="Товары из ваших реальных покупок"><div v-for="(p,i) in heroProducts" :key="p.id" :class="['cover-product','cover-product-'+i]"><img :src="pic(p)" :alt="p.name"><span>{{p.id===byMoney[0]?.id?'Больше всего расходов':p.id===byQty[0]?.id?'Больше всего штук':i%2?'Знакомые вкусы':'Покупки со вкусом'}}</span></div></div></section>
 <section id="story-overview" class="story-chapter"><div class="story-chapter-head"><span class="chapter-count">01</span><div><h2>Вот ваша корзина {{phrases[period]}}.</h2><p>{{rangeLabel}}</p></div></div><div class="story-stats"><div class="story-stat primary"><span>Всего потратили</span><strong>{{money(summary.spend)}}</strong><p>На товары, доставку и упаковку</p></div><div class="story-stat"><span>Получили заказов</span><strong>{{summary.orders}}</strong><p>{{number(summary.goodsQuantity)}} купленных единиц товара</p></div><div class="story-stat"><span>Средняя скидка</span><strong>{{pct(summary.discount)}}</strong><p>{{money(summary.savings)}} осталось благодаря скидкам</p></div></div><div class="story-inline"><span>В среднем <b>{{money(summary.average)}}</b> на заказ</span><span><b>{{summary.goodsProducts}}</b> разных товаров</span><span><b>{{summary.categories}}</b> категорий</span></div></section>
 <section class="story-chapter"><div class="story-chapter-head"><span class="chapter-count">02</span><div><h2>У вашей корзины есть свой ритм.</h2><p>{{series.daily?'Посмотрите, как покупки распределились по дням.':'Месяц на месяц не похож. Посмотрите, когда покупки были самыми большими.'}}</p></div></div><div class="story-time"><div class="story-time-main"><h3>{{series.daily?'Сколько потратили в каждый день':'Сколько уходило на покупки каждый месяц'}}</h3><span class="story-unit">рубли · {{rangeLabel}}</span><TrendChart :data="months" metric="spend" color="#ed8b49" unit="₽" :title="series.daily?'Расходы по дням':'Расходы по месяцам'"/></div><aside class="story-peak"><span>{{series.daily?'Самый большой день':'Самый большой месяц'}}</span><h3>{{dateName(peak.key)}}</h3><strong>{{money(peak.spend)}}</strong><p>{{peak.orders}} заказов и {{number(peak.goodsQuantity)}} единиц товара. Покупки {{series.daily?'за этот день':'за этот месяц в выбранном периоде'}}.</p><span class="story-peak-caption">Показаны покупки только внутри выбранных дат.</span></aside></div></section>
 <section class="story-chapter" v-if="cats.length"><div class="story-chapter-head"><span class="chapter-count">03</span><div><h2>{{threeShare>=50?'Большая часть денег — в нескольких категориях.':'Посмотрим, куда разошлись расходы.'}}</h2><p><b>{{topCategoryNames}}</b> — {{pct(threeShare)}} всех расходов {{phrases[period]}}.</p></div></div><div class="story-category-comparison"><div v-for="c in cats" :key="c.key" class="story-cat-row"><span class="story-cat-name"><i :style="{background:colors[c.key]}"></i>{{c.key}}</span><span class="story-cat-track"><span :style="{width:categoryWidth(c.spend)+'%',background:colors[c.key]}"></span></span><strong>{{money(c.spend)}}</strong><span class="story-cat-share">{{pct(100*c.spend/summary.spend)}}</span></div></div><p class="story-takeaway">Больше всего расходов — на <b>{{cats[0].key.toLowerCase()}}</b>: {{money(cats[0].spend)}}. Длина каждой полосы показывает сумму, а процент рядом — её долю во всей корзине.</p></section>
 <section class="story-chapter" v-if="byQty.length"><div class="story-chapter-head"><span class="chapter-count">04</span><div><h2>{{sameLeader?'Один товар — сразу в двух главных ролях.':'Штуки и рубли рассказывают разные истории.'}}</h2><p>{{sameLeader?'В этот раз лидер по штукам совпал с лидером по расходам.':'Одних товаров купили больше. На другие потратили больше денег.'}}</p></div></div><div class="story-leaders"><article class="story-leader quantity"><span class="leader-label">КУПИЛИ БОЛЬШЕ ВСЕГО</span><div class="leader-photo"><img :src="pic(byQty[0])" :alt="byQty[0].name"></div><h3>{{byQty[0].name}}</h3><strong>{{number(byQty[0].quantity)}} <small>шт.</small></strong><p>{{money(byQty[0].spend)}} {{phrases[period]}}</p></article><article class="story-leader spend"><span class="leader-label">ПОТРАТИЛИ БОЛЬШЕ ВСЕГО</span><div class="leader-photo"><img :src="pic(byMoney[0])" :alt="byMoney[0].name"></div><h3>{{byMoney[0].name}}</h3><strong>{{money(byMoney[0].spend)}}</strong><p>{{number(byMoney[0].quantity)}} купленных единиц товара</p></article></div><p class="story-takeaway">Штуки и рубли отвечают на разные вопросы. Ниже вы сможете сравнить оба рейтинга — для всей корзины и любой категории.</p></section>
 <section class="story-chapter" v-if="purchases.length"><div class="story-chapter-head"><span class="chapter-count">05</span><div><h2>За расходами прячутся цены.</h2><p>Посмотрим на товар с самой большой суммой покупок: <b>{{byMoney[0].name}}</b>.</p></div></div><div class="story-price"><div class="story-price-facts"><div><span>{{dateName(purchases[0].key)}}</span><strong>{{money(purchases[0].value)}} <small>/ шт.</small></strong></div><span v-if="purchases.length>1" class="price-arrow">→</span><div v-if="purchases.length>1"><span>{{dateName(purchases.at(-1).key)}}</span><strong>{{money(purchases.at(-1).value)}} <small>/ шт.</small></strong></div></div><TrendChart :data="history" metric="value" color="#f18b45" unit="₽" :title="series.daily?'Средняя цена купленной единицы товара по дням':'Средняя цена купленной единицы товара по месяцам'"/><p>{{purchases.length===1?'В этом периоде есть только одна точка цены. Для сравнения выберите больший срок.':'Цена купленной единицы после скидок. Пробелы в линии означают, что покупок не было.'}}</p></div></section>
 <section class="story-invitation"><span class="story-kicker">ТЕПЕРЬ ВАША ОЧЕРЕДЬ</span><h2>А какую историю<br>найдёте вы?</h2><p>Выберите время. Загляните в категорию. Сравните любимые товары.<br>Откройте своё пространство для исследования покупок.</p><button class="story-start open-dashboard" @click="emit('open-dashboard',{...range,key:period})">Открыть дашборд <span>↗</span></button></section>
 </div>
</template>
